namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        var decision = ValidatePresence(principal, resource, request);
        if (decision is not null)
            return decision;

        decision = ValidatePrincipalAndResource(principal!, resource!);
        if (decision is not null)
            return decision;

        decision = ValidateRequest(principal!, resource!, request!);
        if (decision is not null)
            return decision;

        return DecideForValidContext(principal!, resource!, request!, delegations);
    }

    private static AccessDecision? ValidatePresence(Principal? principal, Resource? resource, AccessRequest? request)
    {
        return principal is null || resource is null || request is null
            ? new AccessDecision(false, "missing-context", true)
            : null;
    }

    private static AccessDecision? ValidatePrincipalAndResource(Principal principal, Resource resource)
    {
        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
            return new AccessDecision(false, "invalid-identity", true);
        if (principal.Suspended)
            return new AccessDecision(false, "principal-suspended", true);
        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
            return new AccessDecision(false, "tenant-mismatch", true);

        return null;
    }

    private static AccessDecision? ValidateRequest(Principal principal, Resource resource, AccessRequest request)
    {
        if (resource.Locked && request.Action != "read")
            return new AccessDecision(false, "resource-locked", true);
        if (request.MinuteOfDay is < 0 or > 1439)
            return new AccessDecision(false, "invalid-time", true);
        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
            return new AccessDecision(false, "challenge-required", true);

        return null;
    }

    private static AccessDecision DecideForValidContext(
        Principal principal,
        Resource resource,
        AccessRequest request,
        IDelegationRegister delegations)
    {
        var administrator = principal.Roles.Contains("administrator");
        var operatorRole = principal.Roles.Contains("operator");
        var auditor = principal.Roles.Contains("auditor");
        var owner = principal.Id == resource.OwnerId;
        var delegated = delegations.HasDelegation(principal.Id, resource.Id, request.Action);

        if (request.BreakGlass)
            return DecideBreakGlass(administrator, request.StrongAuthentication);

        var restrictionDecision = ApplyClassificationRestrictions(resource, request);
        if (restrictionDecision is not null)
            return restrictionDecision;

        return DecideAction(request, resource, administrator, operatorRole, auditor, owner, delegated);
    }

    private static AccessDecision DecideBreakGlass(bool administrator, bool strongAuthentication)
    {
        return administrator && strongAuthentication
            ? new AccessDecision(true, "break-glass", true)
            : new AccessDecision(false, "invalid-break-glass", true);
    }

    private static AccessDecision? ApplyClassificationRestrictions(Resource resource, AccessRequest request)
    {
        if (resource.Classification != "restricted")
            return null;
        if (!request.StrongAuthentication)
            return new AccessDecision(false, "strong-authentication-required", true);
        if (request.NetworkZone != "trusted")
            return new AccessDecision(false, "trusted-network-required", true);

        return null;
    }

    private static AccessDecision DecideAction(
        AccessRequest request,
        Resource resource,
        bool administrator,
        bool operatorRole,
        bool auditor,
        bool owner,
        bool delegated)
    {
        return request.Action switch
        {
            "delete" => DecideDelete(request, resource, administrator, delegated),
            "write" => DecideWrite(request, resource, administrator, operatorRole, owner, delegated),
            "read" => DecideRead(request, resource, administrator, operatorRole, auditor, owner, delegated),
            _ => new AccessDecision(false, "unknown-action", true)
        };
    }

    private static AccessDecision DecideDelete(
        AccessRequest request,
        Resource resource,
        bool administrator,
        bool delegated)
    {
        return administrator
            ? Allow(request, resource, delegated)
            : new AccessDecision(false, "administrator-required", true);
    }

    private static AccessDecision DecideWrite(
        AccessRequest request,
        Resource resource,
        bool administrator,
        bool operatorRole,
        bool owner,
        bool delegated)
    {
        return administrator || operatorRole || owner || delegated
            ? Allow(request, resource, delegated)
            : new AccessDecision(false, "write-not-authorised", true);
    }

    private static AccessDecision DecideRead(
        AccessRequest request,
        Resource resource,
        bool administrator,
        bool operatorRole,
        bool auditor,
        bool owner,
        bool delegated)
    {
        return administrator || operatorRole || auditor || owner || delegated
            ? Allow(request, resource, delegated)
            : new AccessDecision(false, "read-not-authorised", false);
    }

    private static AccessDecision Allow(AccessRequest request, Resource resource, bool delegated)
    {
        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        var reason = delegated ? "delegated" : "role-or-ownership";
        var auditRequired = outsideBusinessHours || resource.Classification == "restricted";
        return new AccessDecision(true, reason, auditRequired);
    }
}
